contract InvMutTest {
    C c;
    bool didWin;
    uint potBefore;

    constructor(C _c) {
        c = _c;
    }

    function test(uint ticketAmount, uint feeAmount) public {
        require(ticketAmount == 10);
        require(feeAmount == 1);

        potBefore = c.pot();
        (bool success, ) = address(c).call{value: ticketAmount}(abi.encodeWithSignature("play()"));
        didWin = success && c.pot() < potBefore + ticketAmount;

        assert(!didWin || c.pot() == 0);
    }
}

