pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 timestamp, uint256 difficulty) public {
        // 1. Bound the fuzzed block context values to a reasonable range.
        //    They are used in a pseudo-random hash; any block.timestamp and
        //    block.difficulty are admissible as long as they represent a real context.
        timestamp = bound(timestamp, 1, type(uint64).max);
        difficulty = bound(difficulty, 1, type(uint64).max);

        // Set block context so the hash in play() is deterministic and random==0 is possible.
        vm.warp(timestamp);
        vm.roll(difficulty);

        // Fund an EOA and call play() with the exact required ticket amount.
        address player = makeAddr("player");
        vm.deal(player, 1000 ether);
        vm.prank(player);
        c.play{value: 10}();

        // 2. No adversarial external helper is needed — the difference is purely
        //    in the internal state variable `pot`. We only read the public getter.

        // 3. Assert: In the reference version, after any execution of play(),
        //    `pot` is always 0 when the `random == 0` branch was taken.
        //    Since the fuzzer will eventually hit a random == 0 case,
        //    this assertion must hold for the correct contract and fails for the mutant.
        assertTrue(c.pot() == 0);
    }
}

