pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 n, uint256 seed) public {
        // n is number of consecutive wins allowed, keep domain wide
        n = bound(n, 0, 50);
        // Advance block so timestamp/difficulty are not identical on every call
        vm.roll(seed % 1000 + 1);
        vm.warp(seed % 1000000 + 1);

        // Play multiple times, each time sending required ticket amount
        for (uint256 i = 0; i < n; i++) {
            vm.deal(address(this), 10 ether);
            try c.play{value: 10}() {
                // play succeeded; if a win occurred, pot is reset to 0 in correct implementation
            } catch {
                // ignore reverts from potential transfer failures
            }
        }

        // After any sequence, the correct contract ensures pot is less than 10 * number of plays
        // but the buggy contract accumulates pot across wins, so pot can equal n*10.
        // The invariant: pot < 10 if any win happened in the last play or pot <= n*10 always.
        // More precisely: pot must be 0 or 10 (if last was loss).
        // Here we assert: pot % 10 == 0 (always true since only ticket amounts added),
        // but bug violates pot <= 10 after a win sequence (pot could be multiple of 10 > 10).
        // General rule: pot never exceeds 10. Bug breaks this for n>=2 where multiple wins occur.
        assertTrue(c.pot() <= 10);
    }
}

