import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 ticketAmount, uint256 feeAmount, uint256 randomShift) public {
        // Bound the ticket amount to the exact required value to satisfy msg.value check
        ticketAmount = 10;
        feeAmount = 1;
        // We need to influence the random result to trigger the branch where reset should happen.
        // Using block.timestamp and difficulty manipulation to force random == 0.
        // We fuzz the shift to cover many block contexts, but ensure the branch is taken.
        // The rule: after a call that does NOT revert and the branch is taken, pot must be 0.
        // We achieve the branch by setting block.timestamp and difficulty so that keccak256(...) % 2 == 0.
        // However, we can't directly set block.timestamp/difficulty to exact values to guarantee random==0
        // because the hash depends on the actual values. Instead, we bound them such that the branch is always taken
        // by forcing randomShift to 0 (mod 2) and using known deterministic values.
        // Since fuzzer supplies randomShift, we use it to warp to a value that makes the random result predictable.
        // But leaving it fully fuzzed will sometimes not take the branch, making property harder to verify.
        // Instead, we ensure we only check the property when the branch is taken by reading the event or checking pot?
        // No event. The property is: if the call succeeds and random==0, then pot==0.
        // To make the test pass on reference always, we restrict the fuzz so that random==0 is guaranteed.
        // But we don't want to hardcode exact block values. Instead, we loop or use assembly? Not allowed.
        // Alternative: we accept that the property holds for all inputs, but on some inputs the branch may not be taken.
        // The property "after a successful call, if the branch was taken, pot == 0" is too strong because we can't observe branch.
        // We can observe pot before and after. The reference resets pot to 0 on branch taken, otherwise pot stays same (since no change non-random==0).
        // So on any call where pot after is not equal to pot before + ticketAmount (minus fee? no, fee is transferred), the branch was taken and pot should be 0.
        // But fee is transferred out, so balance changes; we can't easily infer branch from pot alone because pot after could be 0 or potBefore+10.
        // The mutant: pot never reset, so after a win pot becomes potBefore+10 (minus fee? no, pot is potBefore+10, fee transferred separate).
        // The invariant is: pot is always either 0 or the sum of contributions since the last win.
        // That is hard to encode without storage history. Another invariant: for any call that does not revert, pot after is always either 0 or potBefore+10.
        // For reference: if win, pot=0; else pot=potBefore+10. For mutant: if win, potAfter = potBefore+10 (not 0).
        // So property: after play(), pot is either 0 or potBefore+10. Reference always satisfies. Mutant breaks when win happens (potAfter = potBefore+10 but should have been 0).
        // That's a valid property.
        uint256 potBefore = c.pot();
        vm.deal(address(this), ticketAmount);
        c.play{value: ticketAmount}();
        uint256 potAfter = c.pot();
        assertTrue(potAfter == 0 || potAfter == potBefore + ticketAmount);
    }
}

