    C c;
    constructor(C _c) { c = _c; }
    function run(uint playCount) public payable {
        require(playCount >= 1);
        uint initialPot = c.pot();
        uint playsWithoutWin = 0;
        for (uint i = 0; i < playCount; i++) {
            uint potBefore = c.pot();
            try c.play{value: 10}() { 
                if (c.pot() != 0) {
                    playsWithoutWin++;
                }
