// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 dummy) public {
        vm.assume(dummy > 0);

        address player = makeAddr("player");
        vm.deal(player, 10 ether);

        // Force a losing play by making random always 1 (non-zero).
        // keccak256(abi.encodePacked(block.timestamp, block.difficulty)) % 2 == 1
        // Set difficulty to 0 => block.difficulty is 0;
        // Set timestamp to 0 => block.timestamp is 0;
        // keccak256(abi.encodePacked(0, 0)) is some fixed hash. Its last bit decides the mod.
        // We can just set difficulty=0 and timestamp=0, which gives a deterministic outcome not equal to 0.
        vm.warp(0);
        vm.roll(0);

        uint256 potBefore = c.pot();
        vm.prank(player);
        c.play{value: 10}();
        uint256 potAfter = c.pot();

        // In the reference version, pot = potBefore + 10 (since random != 0).
        // In the mutant, pot stays 0.
        // So assert that pot increased by exactly 10.
        assertTrue(potAfter == potBefore + 10);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) {
        c = _c;
    }
    function test(uint amount1, uint amount2) public {
        require(address(this).balance >= amount1 + amount2);
        bool r1 = false;
        bool r2 = false;
        if (amount1 != 10) {
            r1 = true;
        }
        if (amount2 != 10) {
            r2 = true;
        }
        if (!r1) {
            c.play{value: amount1}();
        }
        if (!r2) {
            c.play{value: amount2}();
        }
        assert(!r1 || !r2 || c.pot() == 0);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        bool reverted;
        c.play{value: amount}();
        try c.play{value: amount}() { reverted = false; } catch { reverted = true; }
        assert(reverted == (amount != 10));
    }
    receive() external payable {}
}

