            uint256 pseudoRandom = uint256(keccak256(abi.encode(seed, i))) % 2;
            // If pseudoRandom == 0, it's a win in both versions (random == 0 path)
            // We use warp to manipulate block.timestamp so keccak256 inside play matches pseudoRandom
