pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 n, uint8 seed) public {
        // n: number of plays, seed: influences win/loss by warping timestamp
        // Keep domain wide but avoid extreme block difficulty that distorts randomness
        vm.assume(n > 0 && n <= 50);
        uint256 totalContributed = 0;
        uint256 wins = 0;
        for (uint256 i = 0; i < n; i++) {
            vm.warp(block.timestamp + (seed * (i + 1)));
            vm.roll(block.number + 1);
            address player = address(uint160(uint256(keccak256(abi.encode(i, seed)))));
            vm.deal(player, 10);
            vm.prank(player);
            c.play{value: 10}();
            totalContributed += 10;
            uint256 random = uint256(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2;
            if (random == 0) {
                wins += 1;
            }
        }
        // Invariant: pot <= totalContributed - wins * FEE_AMOUNT (FEE_AMOUNT = 1)
        // Because payouts remove pot, and bank fee is 1 per win. Mutant never resets, so pot grows beyond this bound.
        assertTrue(c.pot() <= totalContributed - (wins * 1));
    }
}

